// Procesa todos los emails y extrae un item por cada PDF adjunto
const items = [];

for (const data of $input.all()) {
  const binary = data.binary || {};
  const attKeys = Object.keys(binary).filter(k => k.startsWith('attachment_'));

  if (attKeys.length === 0) continue;

  for (const key of attKeys) {
    const mime = binary[key].mimeType || '';
    const fname = (binary[key].fileName || key).toLowerCase();
    if (mime.includes('pdf') || fname.endsWith('.pdf')) {
      items.push({
        json: {
          subject: data.json.subject || 'Sin asunto',
          from: data.json.from || 'gometrix.dev',
          fileName: binary[key].fileName || key
        },
        binary: { pdf_attachment: binary[key] }
      });
    }
  }
}

if (items.length === 0) {
  // Sin PDFs: devolver item especial para que el reporte lo indique
  return [{ json: { _noPdfs: true, text: '', subject: '', from: '', fileName: '' } }];
}

return items;

// Leer sprints del nodo Aggregate y construir prompt
const sprints = ($json.sprints || []).filter(s =>
  !s._noPdfs && s.text && s.text.trim().length > 20
);

const fecha = new Date().toLocaleDateString('es-CO', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

if (sprints.length === 0) {
  return [{ json: {
    prompt: `No se recibieron reportes de sprint con PDF esta semana (${fecha}). Por favor verificar que los correos de gometrix.dev tengan archivos PDF adjuntos.`,
    sprintCount: 0,
    fecha
  }}];
}

let prompt = `FECHA DE REVISIÓN: ${fecha}\nTOTAL DE REPORTES RECIBIDOS: ${sprints.length}\n\n=== REPORTES DE SPRINT PARA ANÁLISIS ===\n\n`;

sprints.forEach((s, i) => {
  prompt += `--- REPORTE ${i + 1} ---\nAsunto: ${s.subject}\nDe: ${s.from}\nArchivo: ${s.fileName}\n\nContenido:\n${s.text}\n\n`;
});

return [{ json: { prompt, sprintCount: sprints.length, fecha, reportDate: new Date().toISOString() } }];

// Convertir markdown del AI a HTML limpio para el correo
const text = $json.output || 'Error: no se generó análisis';
const hoy = new Date();
const fecha = hoy.toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric' });
const fechaHora = hoy.toLocaleDateString('es-CO', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });

let html = text
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/^# (.+)$/gm, '<h1 style="color:#1a3c5e;border-bottom:2px solid #1a3c5e;padding-bottom:6px;margin-top:0">$1</h1>')
  .replace(/^## (.+)$/gm, '<h2 style="color:#1a3c5e;margin-top:24px">$1</h2>')
  .replace(/^### (.+)$/gm, '<h3 style="color:#2e6da4;margin-top:16px">$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/^- (.+)$/gm, '<li>$1</li>')
  .replace(/^---$/gm, '<hr style="border:none;border-top:1px solid #ddd;margin:20px 0">')
  .replace(/\n/g, '<br>');

const htmlBody = `<div style="font-family:Arial,sans-serif;max-width:840px;margin:auto;padding:28px;color:#1a1a1a;line-height:1.6">${html}<hr style="margin-top:36px;border:none;border-top:1px solid #ddd"><p style="color:#999;font-size:11px">Generado automáticamente · Gometrix AI Board Manager · ${fechaHora}</p></div>`;

return [{ json: {
  htmlBody,
  emailSubject: `📊 Board Manager Report – Sprints Gometrix ${fecha}`
} }];
